import 'dart:convert';

/// Represents the QR pairing payload generated by `/apir_desktop/server.py`:
/// `{"app": "apir", "uri": "ws://<local_ip>:8765", "host": "<computer_hostname>", "token": "<4_digit_session_pin>"}`
class PairingPayload {
  final String app;
  final String uri;
  final String host;
  final String token;

  const PairingPayload({
    required this.app,
    required this.uri,
    required this.host,
    required this.token,
  });

  factory PairingPayload.fromJson(Map<String, dynamic> json) {
    final app = (json['app'] ?? '').toString().trim();
    final uri = (json['uri'] ?? '').toString().trim();
    final host = (json['host'] ?? 'Laptop').toString().trim();
    final token = (json['token'] ?? '').toString().trim();

    if (app != 'apir' || uri.isEmpty || token.isEmpty) {
      throw const FormatException('Invalid Apir QR pairing payload.');
    }

    return PairingPayload(
      app: app,
      uri: uri,
      host: host.isEmpty ? 'Laptop' : host,
      token: token,
    );
  }

  static PairingPayload? tryParseRaw(String rawValue) {
    final trimmed = rawValue.trim();

    // 1. Support direct JSON QR payload:
    // {"app": "apir", "uri": "ws://<ip>:8765", "host": "<host>", "token": "<pin>"}
    try {
      final decoded = jsonDecode(trimmed);
      if (decoded is Map<String, dynamic>) {
        return PairingPayload.fromJson(decoded);
      }
    } catch (_) {}

    // 2. Support universal HTTP/WS QR URL payload:
    // http://<ip>:8765/?app=apir&uri=ws://<ip>:8765&host=<host>&token=<pin>
    try {
      final parsedUri = Uri.parse(trimmed);
      final qp = parsedUri.queryParameters;
      if (qp['app'] == 'apir' && (qp['token'] ?? '').isNotEmpty) {
        final wsUri = (qp['uri'] ?? '').isNotEmpty
            ? qp['uri']!
            : 'ws://${parsedUri.host}:${parsedUri.hasPort ? parsedUri.port : 8765}';
        return PairingPayload(
          app: 'apir',
          uri: wsUri,
          host: (qp['host'] ?? parsedUri.host).toString(),
          token: qp['token']!,
        );
      }
    } catch (_) {}

    return null;
  }

  Map<String, dynamic> toJson() => {
        'app': app,
        'uri': uri,
        'host': host,
        'token': token,
      };

  String toRawJson() => jsonEncode(toJson());
}
